llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Brigatinib, a close structural analogue sharing the piperazine and aminopyridine/pyrimidine motifs, has an approximate absolute oral bioavailability of 46% in healthy volunteers, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Linezolid has an absolute oral bioavailability of 100% at a 375 mg oral dose, demonstrating that high-transfer compounds in this evidence set can achieve complete oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Encainide shows an absolute oral bioavailability of 20–30% in healthy subjects, meeting the F ≥ 20% threshold despite variable first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Paliperidone extended-release has an absolute oral bioavailability of 28% in healthy volunteers, supporting high classification for a moderately absorbed heteroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Rifapentine has an absolute oral bioavailability of 70% after a single 600 mg dose in healthy volunteers, showing that large, lipophilic, polycyclic molecules can be highly orally bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Ketanserin has an absolute oral bioavailability of 46.8% in healthy male subjects, providing another direct human F measurement well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Tacrolimus, despite incomplete absorption, has an oral bioavailability of approximately 20–25%, still meeting the F ≥ 20% threshold and supporting high classification.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a pyrido[2,3-d]pyrimidinone kinase inhibitor with a piperazinyl-anilinopyridine substituent, matching the palbociclib chemotype. All transferable experimental evidence points to oral bioavailability at or above 20%: the closest analogue brigatinib has F ≈ 46%, and other high-transfer drugs range from ~20–25% (tacrolimus) to ~100% (linezolid). No affirmative evidence of F < 20% was identified, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is present in the provided evidence; the prediction relies on high-transfer analogues.",
    "Some analogues show formulation- or disease-dependent bioavailability (e.g., paliperidone ER 28% vs IR ~100%; encainide 20–30% in healthy subjects vs 78% in cirrhosis), but all central estimates meet the 20% threshold.",
    "Tacrolimus at ~20–25% is close to the threshold, adding minor boundary uncertainty, though it remains in the high category."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

